import { cookies } from 'next/headers';

export async function createSession(token: string) {
  const cookieStore = await cookies();

  cookieStore.set('session_id', token, {
    httpOnly: true,
    secure: true,
    sameSite: 'strict',
    path: '/',
    maxAge: 60 * 60 * 24 * 7, // 1 week expiry
  });
}
